fulfill.run:
$utils.setAsBlockRoot($self)
const rootEntire = $self.address.entire
const CONFIG_KEY = 'translationConfig'
const MODEL_KEY = 'modelProviderConfig'
$self.state = $observable({ translationConfig: null, modelProviderConfig: [], selectedProviderId: '' })
const DEFAULT_CONFIG = {
  translationEnabled: false,
  translationProviderId: 'deepseek',
  translationModel: 'deepseek-v4-flash',
  targetLanguage: '简体中文',
  sourceLanguage: 'auto',
  translationDisplayMode: 'bilingual',
  autoTranslateOnPageLoad: false,
  translationConcurrency: 4,
  showFloatingBall: true,
  hoverParagraphTranslate: true,
  dynamicContentTranslate: true,
  enableCache: true,
  paragraphTranslateShortcut: 'double-ctrl'
}
$self.loadModelProviders = async () => {
  const res = await $chrome.storage.local.get(MODEL_KEY)
  $self.state.modelProviderConfig = (res && Array.isArray(res[MODEL_KEY])) ? res[MODEL_KEY] : []
}
$self.loadTranslationConfig = async () => {
  const res = await $chrome.storage.local.get(CONFIG_KEY)
  const cfg = res && res[CONFIG_KEY] && typeof res[CONFIG_KEY] === 'object' ? res[CONFIG_KEY] : null
  $self.state.translationConfig = cfg || DEFAULT_CONFIG
  $self.state.selectedProviderId = (cfg || DEFAULT_CONFIG).translationProviderId || ''
}
$self.saveTranslationConfig = async (config) => {
  const plain = JSON.parse(JSON.stringify(config || {}))
  await $chrome.storage.local.set({ [CONFIG_KEY]: plain })
  $self.state.translationConfig = plain
}
$effect(() => {
  (async () => {
    await $self.loadModelProviders()
    await $self.loadTranslationConfig()
  })()
}, [])

const rf = $utils.getBlockRootField($self)
if (!rf) return
$props({ onChange: async (val) => {
  const formField = rf.query(rf.address.entire + '.translationConfigForm').take()
  if (!formField || !formField.value) return
  formField.value.translationEnabled = val
  await rf.saveTranslationConfig(formField.value)
  $message.success(val ? '翻译功能已开启' : '翻译功能已关闭')
} })

const rf = $utils.getBlockRootField($self)
$props({
  onClick: async () => {
    if (!rf) return
    const formField = rf.query(rf.address.entire + '.translationConfigForm').take()
    if (!formField) return
    const config = formField.value || {}
    if (!config.translationProviderId) { $message.error('请选择翻译提供方'); return }
    if (!config.translationModel) { $message.error('请选择翻译模型'); return }
    await rf.saveTranslationConfig(config)
    $message.success('保存成功')
  }
})

const rf = $utils.getBlockRootField($self)
$effect(() => {
  if (!rf || !rf.state || !rf.state.translationConfig) return
  $self.value = rf.state.translationConfig
  const enabledField = rf.query(rf.address.entire + '.headerDiv.enableGroup.translationEnabled').take()
  if (enabledField) enabledField.value = rf.state.translationConfig.translationEnabled || false
}, [rf.state.translationConfig])

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$effect(() => {
  $self.dataSource = (rf.state.modelProviderConfig || []).map((p) => ({ label: p.name, value: p.id }))
}, [rf.state.modelProviderConfig])

$props({ onChange: (val) => {
  rf.state.selectedProviderId = val
  const formVal = $self.parent && $self.parent.value
  if (formVal) formVal.translationModel = ''
} })

const rf = $utils.getBlockRootField($self)
if (!rf || !rf.state) return
$effect(() => {
  const providerId = rf.state.selectedProviderId
  const provider = (rf.state.modelProviderConfig || []).find((p) => p.id === providerId)
  $self.dataSource = (provider && provider.models || []).map((m) => ({ label: m.model, value: m.model }))
}, [rf.state.modelProviderConfig, rf.state.selectedProviderId])

$utils.setAsBlockRoot($self)
const rootEntire = $self.address.entire
const STORAGE_KEY = 'translationHistory'
$self.state = $observable({ list: null })
$self.fetchList = async () => {
  if ($self.state.list) return $self.state.list
  const res = await $chrome.storage.local.get(STORAGE_KEY)
  const list = res && Array.isArray(res[STORAGE_KEY]) ? res[STORAGE_KEY] : []
  $self.state.list = list
  return list
}
$self.saveList = async (list) => {
  const plain = JSON.parse(JSON.stringify(list))
  await $chrome.storage.local.set({ [STORAGE_KEY]: plain })
  $self.state.list = plain
}
$self.showEditDialog = (item) => {
  if (!item) return
  const dlg = $self.query(rootEntire + '.editItemDialog').take()
  if (!dlg) return
  dlg.value = { source: item.source || '', translation: item.translation || '', __editIndex: item.__index }
  dlg.setComponentProps({ open: true, title: '修改翻译历史' })
}
$self.updateItem = async (form) => {
  const source = (form.source || '').trim()
  if (!source) { $message.error('源文不能为空'); return false }
  const translation = (form.translation || '').trim()
  if (!translation) { $message.error('译文不能为空'); return false }
  const list = (await $self.fetchList()).slice()
  const editIndex = form.__editIndex
  if (editIndex == null || editIndex < 0 || editIndex >= list.length) return false
  list[editIndex] = { ...list[editIndex], source, translation }
  await $self.saveList(list)
  $message.success('修改成功')
  return true
}
$self.deleteItem = async (item) => {
  const list = (await $self.fetchList()).slice()
  const idx = item.__index
  if (idx == null || idx < 0 || idx >= list.length) return
  list.splice(idx, 1)
  await $self.saveList(list)
  $message.success('删除成功')
}
$self.clearAll = async () => {
  await $self.saveList([])
  $message.success('已清空全部翻译历史')
}
$effect(() => { $self.fetchList() }, [])

const rf = $utils.getBlockRootField($self)
$effect(() => {
  $self.value = (rf.state.list || []).map((item, i) => ({
    ...item,
    timeDisplay: item.time ? $dayjs(item.time).format('YYYY-MM-DD HH:mm:ss') : '',
    __index: i
  }))
}, [rf.state.list])

const rf = $utils.getBlockRootField($self)
$props({
  onCancel: () => { $self.componentProps.open = false },
  onOk: () => {
    $self.validate().then(async () => {
      const form = $self.value
      if (!rf) return
      const ok = await rf.updateItem(form)
      if (ok) $self.componentProps.open = false
    }).catch((e) => { $logger.info('表单校验失败', e) })
  }
})

$utils.setAsBlockRoot($self)
const rootEntire = $self.address.entire
const STORAGE_KEY = 'translationWordbook'
const MAX_COUNT = 200
$self.state = $observable({ list: null })
$self.fetchList = async () => {
  if ($self.state.list) return $self.state.list
  const res = await $chrome.storage.local.get(STORAGE_KEY)
  const list = res && Array.isArray(res[STORAGE_KEY]) ? res[STORAGE_KEY] : []
  $self.state.list = list
  return list
}
$self.saveList = async (list) => {
  const plain = JSON.parse(JSON.stringify(list))
  await $chrome.storage.local.set({ [STORAGE_KEY]: plain })
  $self.state.list = plain
}
$self.showAddOrUpdateDialog = (item) => {
  const dlg = $self.query(rootEntire + '.addOrUpdateItemDialog').take()
  if (!dlg) return
  if (item) {
    dlg.value = { source: item.source || '', translation: item.translation || '', __editIndex: item.__index }
  } else {
    dlg.value = { source: '', translation: '', __editIndex: -1 }
  }
  dlg.setComponentProps({ open: true, title: item ? '修改单词' : '添加单词' })
}
$self.addOrUpdateItem = async (form) => {
  const source = (form.source || '').trim()
  if (!source) { $message.error('源文不能为空'); return false }
  const translation = (form.translation || '').trim()
  if (!translation) { $message.error('译文不能为空'); return false }
  const list = (await $self.fetchList()).slice()
  const editIndex = form.__editIndex
  if (editIndex != null && editIndex >= 0 && editIndex < list.length) {
    list[editIndex] = { ...list[editIndex], source, translation }
  } else {
    if (list.some((w) => w.source === source && w.translation === translation)) {
      $message.error('该单词已存在')
      return false
    }
    list.unshift({ source, translation, time: Date.now() })
    if (list.length > MAX_COUNT) list.length = MAX_COUNT
  }
  await $self.saveList(list)
  $message.success(editIndex != null && editIndex >= 0 ? '修改成功' : '添加成功')
  return true
}
$self.deleteItem = async (item) => {
  const list = (await $self.fetchList()).slice()
  const idx = item.__index
  if (idx == null || idx < 0 || idx >= list.length) return
  list.splice(idx, 1)
  await $self.saveList(list)
  $message.success('删除成功')
}
$self.clearAll = async () => {
  await $self.saveList([])
  $message.success('已清空全部单词')
}
$effect(() => { $self.fetchList() }, [])

const rf = $utils.getBlockRootField($self)
$effect(() => {
  $self.value = (rf.state.list || []).map((item, i) => ({
    ...item,
    timeDisplay: item.time ? $dayjs(item.time).format('YYYY-MM-DD HH:mm:ss') : '',
    __index: i
  }))
}, [rf.state.list])

const rf = $utils.getBlockRootField($self)
$props({
  onCancel: () => { $self.componentProps.open = false },
  onOk: () => {
    $self.validate().then(async () => {
      const form = $self.value
      if (!rf) return
      const ok = await rf.addOrUpdateItem(form)
      if (ok) $self.componentProps.open = false
    }).catch((e) => { $logger.info('表单校验失败', e) })
  }
})
